INSERT INTO faqs (
  slug, category, question_en, question_fi, answer_en, answer_fi,
  display_order, is_active, inserted_at, updated_at
) VALUES (
  'how-to-create-first-post',
  'user',
  'How do I create my first blog post?',
  'Miten luon ensimmäisen blogikirjoitukseni?',
  '<p>To create your first blog post on Portal of JH:</p>
<ol>
  <li>Log in to your account</li>
  <li>Click "Posts" in the navigation menu</li>
  <li>Click the "New Post" button</li>
  <li>Enter a title and write your content using Markdown</li>
  <li>Add tags to categorize your post (optional)</li>
  <li>Click "Save Post" to publish</li>
</ol>
<p>Your post will be visible on the homepage once published!</p>',
  '<p>Luodaksesi ensimmäisen blogikirjoituksesi Portal of JH:ssa:</p>
<ol>
  <li>Kirjaudu sisään tilillesi</li>
  <li>Klikkaa "Julkaisut" navigointivalikossa</li>
  <li>Klikkaa "Uusi julkaisu" -painiketta</li>
  <li>Kirjoita otsikko ja sisältö Markdown-muodossa</li>
  <li>Lisää tageja kategorisoidaksesi kirjoituksesi (valinnainen)</li>
  <li>Klikkaa "Tallenna julkaisu" julkaistaksesi</li>
</ol>
<p>Julkaisusi näkyy etusivulla kun se on julkaistu!</p>',
