INSERT INTO faqs (
  slug, category, question_en, question_fi, answer_en, answer_fi,
  display_order, is_active, inserted_at, updated_at
) VALUES (
  'formatting-options',
  'user',
  'What formatting options are available for my posts?',
  'Mitä muotoiluvaihtoehtoja kirjoituksilleni on saatavilla?',
  '<p>Portal of JH uses Markdown for post formatting. Here are the most common examples you can copy and use:</p>

<h3>Text Formatting</h3>
<pre><code>**Bold text**
*Italic text*
***Bold and italic***
~~Strikethrough~~</code></pre>

<h3>Headers</h3>
<pre><code># Heading 1
## Heading 2
### Heading 3</code></pre>

<h3>Links and Images</h3>
<pre><code>[Link text](https://example.com)
![Image alt text](https://example.com/image.jpg)</code></pre>

<h3>Lists</h3>
<pre><code>- Unordered item 1
- Unordered item 2
  - Nested item

1. Ordered item 1
2. Ordered item 2</code></pre>

<h3>Code</h3>
<pre><code>Inline `code` with backticks

```elixir
# Code block with syntax highlighting
def hello(name) do
  IO.puts("Hello, #{name}!")
end
```</code></pre>

<h3>Blockquotes</h3>
<pre><code>&gt; This is a quote
&gt; It can span multiple lines</code></pre>

<p>Just copy these examples and modify them for your content!</p>',
  '<p>Portal of JH käyttää Markdown-muotoilua julkaisuissa. Tässä yleisimmät esimerkit joita voit kopioida ja käyttää:</p>

<h3>Tekstin muotoilu</h3>
<pre><code>**Lihavoitu teksti**
*Kursivoitu teksti*
***Lihavoitu ja kursivoitu***
~~Yliviivattu~~</code></pre>

<h3>Otsikot</h3>
<pre><code># Otsikko 1
## Otsikko 2
### Otsikko 3</code></pre>

<h3>Linkit ja kuvat</h3>
<pre><code>[Linkin teksti](https://esimerkki.fi)
![Kuvan alt-teksti](https://esimerkki.fi/kuva.jpg)</code></pre>

<h3>Listat</h3>
<pre><code>- Järjestämätön kohta 1
- Järjestämätön kohta 2
  - Sisäkkäinen kohta

1. Järjestetty kohta 1
2. Järjestetty kohta 2</code></pre>

<h3>Koodi</h3>
<pre><code>Rivinsisäinen `koodi` backtick-merkeillä

```elixir
# Koodilohko syntaksikorostuksella
def tervehdys(nimi) do
  IO.puts("Hei, #{nimi}!")
end
```</code></pre>

<h3>Lainaukset</h3>
<pre><code>&gt; Tämä on lainaus
&gt; Se voi olla useammalla rivillä</code></pre>

<p>Kopioi nämä esimerkit ja muokkaa niitä sisällöllesi!</p>',
  2,
  true,
  '2025-11-28T14:53:38Z',
  '2025-11-28T14:53:38Z'
) ON CONFLICT (slug) DO UPDATE SET
  category = EXCLUDED.category,
  question_en = EXCLUDED.question_en,
