INSERT INTO faqs (
  slug, category, question_en, question_fi, answer_en, answer_fi,
  display_order, is_active, inserted_at, updated_at
) VALUES (
  'rss-subscription',
  'user',
  'Can readers subscribe to my blog?',
  'Voivatko lukijat tilata blogini?',
  '<p>Yes! Portal of JH provides multiple subscription options:</p>
<ul>
  <li><strong>RSS Feed:</strong> Subscribe to receive updates in your RSS reader</li>
  <li><strong>Atom Feed:</strong> Alternative XML feed format</li>
  <li><strong>JSON Feed:</strong> Modern JSON-based feed format</li>
</ul>
<p>Feed links are available in the footer of every page. Each post includes reading time estimates to help you plan your reading!</p>',
  '<p>Kyllä! Portal of JH tarjoaa useita tilausvaihtoehtoja:</p>
<ul>
  <li><strong>RSS-syöte:</strong> Tilaa päivitykset RSS-lukijallesi</li>
  <li><strong>Atom-syöte:</strong> Vaihtoehtoinen XML-syöteformaatti</li>
  <li><strong>JSON-syöte:</strong> Moderni JSON-pohjainen syöte</li>
</ul>
<p>Syötelinkit löytyvät jokaisen sivun alatunnisteesta. Jokainen julkaisu sisältää lukuajan arvion lukemisen suunnitteluun!</p>',
